<?php
require 'db.php'; session_start(); require 'includes.php';
if (($_SESSION['user_role'] ?? '') !== 'admin') { header('Location: login.php'); exit; }
$requests=$conn->query('SELECT req.*,u.name,u.email,u.branch,r.room_number,r.room_type FROM room_requests req JOIN users u ON u.id=req.user_id JOIN rooms r ON r.id=req.room_id ORDER BY req.created_at DESC');
?><!doctype html><html><head><meta charset="utf-8"><title>Room Requests Export</title><style>body{font-family:Arial;color:#172033;padding:25px}h1{margin-bottom:4px}p{color:#667085}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:10px;border:1px solid #d0d5dd;text-align:left;font-size:12px}th{background:#eef2ff}@media print{button{display:none}body{padding:0}}</style></head><body><button onclick="window.print()">Save as PDF / Print</button><h1>StaySpace · Room Requests</h1><p>Generated <?=date('d M Y, h:i A')?></p><table><thead><tr><th>Student</th><th>Roll no.</th><th>Room</th><th>Plan</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php while($r=$requests->fetch_assoc()):?><tr><td><?=e($r['name'])?><br><?=e($r['email'])?></td><td><?=e($r['roll_no'])?></td><td><?=e($r['room_number'])?> · <?=e($r['room_type'])?></td><td><?=e($r['stay_duration'])?></td><td>₹<?=number_format($r['final_amount'])?></td><td><?=e($r['status'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td></tr><?php endwhile;?></tbody></table><script>window.onload=()=>window.print()</script></body></html>
